// Globe by Abisto: offline copy of the game. Generated by build.js from src/sw.template.js; don't edit sw.js by hand.
const CACHE = "globe-__VERSION__";
const FILES = __FILES__;

self.addEventListener("install", e => {
  // cache: "reload" skips the browser's own short-term copy, so a new version really downloads the new files
  e.waitUntil(caches.open(CACHE).then(c => c.addAll(FILES.map(f => new Request(f, { cache: "reload" })))).then(() => self.skipWaiting()));
});

self.addEventListener("activate", e => {
  e.waitUntil(
    caches.keys()
      .then(keys => Promise.all(keys.filter(k => k.startsWith("globe-") && k !== CACHE).map(k => caches.delete(k))))
      .then(() => self.clients.claim())
  );
});

// The game's own files come from the saved copy (instant, and works offline).
// Anything else, like the leaderboard, goes to the network as usual.
self.addEventListener("fetch", e => {
  const req = e.request;
  if (req.method !== "GET" || new URL(req.url).origin !== location.origin) return;
  if (req.mode === "navigate") {
    e.respondWith(caches.match("./", { cacheName: CACHE }).then(r => r || fetch(req)).catch(() => caches.match("index.html")));
    return;
  }
  e.respondWith(caches.match(req, { cacheName: CACHE, ignoreSearch: true }).then(r => r || fetch(req)));
});
